package main

import (
	"bufio"
	"fmt"
	"math"
	"math/rand"
	"os"
	"strconv"
	"strings"
	"time"

	"freelang-llm/model"
)

type Vocab struct {
	ByteToIdx [256]int
	IdxToByte []byte
	Size      int
}

func loadVocab(path string) (*Vocab, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()
	v := &Vocab{}
	for i := range v.ByteToIdx { v.ByteToIdx[i] = -1 }
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "vocab_size=") { continue }
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 { continue }
		idx, _ := strconv.Atoi(parts[0])
		byteVal, _ := strconv.Atoi(parts[1])
		v.ByteToIdx[byteVal] = idx
		if idx >= len(v.IdxToByte) {
			v.IdxToByte = append(v.IdxToByte, make([]byte, idx-len(v.IdxToByte)+1)...)
		}
		v.IdxToByte[idx] = byte(byteVal)
		if idx+1 > v.Size { v.Size = idx + 1 }
	}
	return v, nil
}

func encode(text string, v *Vocab) []int {
	ids := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ {
		idx := v.ByteToIdx[text[i]]
		if idx >= 0 { ids = append(ids, idx) }
	}
	return ids
}

func decode(ids []int, v *Vocab) string {
	out := make([]byte, 0, len(ids))
	for _, id := range ids {
		if id < len(v.IdxToByte) { out = append(out, v.IdxToByte[id]) }
	}
	return string(out)
}

func loadModel(path string) (*model.GPTParams, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024*1024), 64*1024*1024)

	scanner.Scan()
	header := scanner.Text()
	cfg := model.Config{}
	for _, part := range strings.Fields(header) {
		kv := strings.SplitN(part, "=", 2)
		if len(kv) != 2 { continue }
		val, _ := strconv.Atoi(kv[1])
		switch kv[0] {
		case "vocab":   cfg.VocabSize = val
		case "dmodel":  cfg.DModel = val
		case "layers":  cfg.NLayers = val
		case "seq":     cfg.SeqLen = val
		case "ffn":     cfg.FFNDim = val
		}
	}

	p := model.NewGPTParams(cfg)
	matrices := map[string]*model.Matrix{
		"token_emb":      p.TokenEmb,
		"pos_emb":        p.PosEmb,
		"final_ln_scale": p.FinalLnScale,
		"final_ln_bias":  p.FinalLnBias,
		"lm_head":        p.LMHead,
		"lm_bias":        p.LMBias,
	}
	for i := range p.Blocks {
		pf := fmt.Sprintf("block%d", i)
		bp := &p.Blocks[i]
		matrices[pf+"_wq"] = bp.Wq; matrices[pf+"_wk"] = bp.Wk
		matrices[pf+"_wv"] = bp.Wv; matrices[pf+"_wo"] = bp.Wo
		matrices[pf+"_bq"] = bp.Bq; matrices[pf+"_bk"] = bp.Bk
		matrices[pf+"_bv"] = bp.Bv; matrices[pf+"_bo"] = bp.Bo
		matrices[pf+"_w1"] = bp.W1; matrices[pf+"_b1"] = bp.B1
		matrices[pf+"_w2"] = bp.W2; matrices[pf+"_b2"] = bp.B2
		matrices[pf+"_ln1s"] = bp.Ln1Scale; matrices[pf+"_ln1b"] = bp.Ln1Bias
		matrices[pf+"_ln2s"] = bp.Ln2Scale; matrices[pf+"_ln2b"] = bp.Ln2Bias
	}

	for scanner.Scan() {
		nameLine := scanner.Text()
		parts := strings.Fields(nameLine)
		if len(parts) < 3 { continue }
		name := parts[0]
		rows, _ := strconv.Atoi(parts[1])
		cols, _ := strconv.Atoi(parts[2])
		scanner.Scan()
		valLine := scanner.Text()
		vals := strings.Fields(valLine)
		m := model.NewMatrix(rows, cols)
		for i, s := range vals {
			if i < len(m.Data) {
				v, _ := strconv.ParseFloat(s, 32)
				m.Data[i] = float32(v)
			}
		}
		if target, ok := matrices[name]; ok {
			copy(target.Data, m.Data)
		}
	}
	return p, nil
}

// Top-k sampling
func topKSample(logits *model.Matrix, k int, temp float32) int {
	n := logits.Cols
	if k <= 0 || k > n { k = n }

	// scale by temperature
	scaled := make([]float32, n)
	for i, v := range logits.Data { scaled[i] = v / temp }

	// find top-k indices
	type pair struct{ idx int; val float32 }
	pairs := make([]pair, n)
	for i, v := range scaled { pairs[i] = pair{i, v} }
	// partial sort: selection
	for i := 0; i < k; i++ {
		maxJ := i
		for j := i + 1; j < n; j++ {
			if pairs[j].val > pairs[maxJ].val { maxJ = j }
		}
		pairs[i], pairs[maxJ] = pairs[maxJ], pairs[i]
	}

	// softmax over top-k
	topK := pairs[:k]
	maxV := topK[0].val
	var sum float32
	probs := make([]float32, k)
	for i, p := range topK {
		probs[i] = float32(math.Exp(float64(p.val - maxV)))
		sum += probs[i]
	}
	for i := range probs { probs[i] /= sum }

	r := rand.Float32()
	cumsum := float32(0)
	for i, prob := range probs {
		cumsum += prob
		if r <= cumsum { return topK[i].idx }
	}
	return topK[k-1].idx
}

func generate(p *model.GPTParams, prompt []int, maxNew int, v *Vocab, temp float32) []int {
	ids := make([]int, len(prompt))
	copy(ids, prompt)
	seqLen := p.Cfg.SeqLen
	for i := 0; i < maxNew; i++ {
		// take last seqLen tokens
		ctx := ids
		if len(ctx) > seqLen { ctx = ctx[len(ctx)-seqLen:] }
		logits := model.Forward(p, ctx)
		nextID := topKSample(logits, 5, temp)
		ids = append(ids, nextID)
	}
	return ids[len(prompt):]
}

func main() {
	rand.Seed(time.Now().UnixNano())

	dataDir := os.ExpandEnv("$HOME/projects/freelang-llm/data")
	modelPath := os.ExpandEnv("$HOME/projects/freelang-llm/model/model.bin")

	v, err := loadVocab(dataDir + "/vocab.txt")
	if err != nil { fmt.Fprintf(os.Stderr, "vocab: %v\n", err); os.Exit(1) }

	p, err := loadModel(modelPath)
	if err != nil { fmt.Fprintf(os.Stderr, "model: %v\n", err); os.Exit(1) }
	fmt.Printf("모델 로드 완료 (vocab=%d, d=%d, layers=%d)\n\n", p.Cfg.VocabSize, p.Cfg.DModel, p.Cfg.NLayers)

	// Interactive REPL
	scanner := bufio.NewScanner(os.Stdin)
	fmt.Println("=== FreeLang LLM 추론 엔진 ===")
	fmt.Println("프롬프트를 입력하세요 (exit으로 종료):")
	for {
		fmt.Print("\n> ")
		if !scanner.Scan() { break }
		prompt := scanner.Text()
		if prompt == "exit" || prompt == "quit" { break }
		if prompt == "" { continue }

		ids := encode(prompt, v)
		if len(ids) == 0 {
			fmt.Println("인코딩 실패: 알 수 없는 문자")
			continue
		}
		if len(ids) > p.Cfg.SeqLen { ids = ids[len(ids)-p.Cfg.SeqLen:] }

		fmt.Printf("\n[생성 중...]\n%s", prompt)
		generated := generate(p, ids, 200, v, 0.8)
		fmt.Println(decode(generated, v))
	}
}

