			Wv: RandMatrix(cfg.DModel, cfg.DModel, scale),
			Wo: RandMatrix(cfg.DModel, cfg.DModel, scale),
			Bq: ZeroMatrix(1, cfg.DModel),
			Bk: ZeroMatrix(1, cfg.DModel),
			Bv: ZeroMatrix(1, cfg.DModel),
			Bo: ZeroMatrix(1, cfg.DModel),
			W1: RandMatrix(cfg.DModel, cfg.FFNDim, scale),
			B1: ZeroMatrix(1, cfg.FFNDim),
			W2: RandMatrix(cfg.FFNDim, cfg.DModel, scale),
			B2: ZeroMatrix(1, cfg.DModel),
			Ln1Scale: OnesVec(cfg.DModel),
			Ln1Bias:  ZeroMatrix(1, cfg.DModel),
			Ln2Scale: OnesVec(cfg.DModel),
			Ln2Bias:  ZeroMatrix(1, cfg.DModel),
		}
		p.Blocks = append(p.Blocks, bp)
	}
	return p
}

// linear: x(seq x in) @ W(in x out) + b(1 x out) -> seq x out
func linear(x, W, b *Matrix, seq int) *Matrix {
	out := Matmul(x, W)
	for r := 0; r < seq; r++ {
		for c := 0; c < out.Cols; c++ {
			out.Data[r*out.Cols+c] += b.Data[c]
		}
	}
	return out
}

// causal self-attention (single head for simplicity, projected)
func attentionBlock(x *Matrix, bp BlockParams, seq, d int) *Matrix {
	Q := linear(x, bp.Wq, bp.Bq, seq)
	K := linear(x, bp.Wk, bp.Bk, seq)
	V := linear(x, bp.Wv, bp.Bv, seq)

	scale := float32(1.0 / math.Sqrt(float64(d)))
	scores := ScaleMat(Matmul(Q, Transpose(K)), scale)
	mask := CausalMask(seq)
	scores = AddMat(scores, mask)
	attnW := SoftmaxRows(scores)
	ctx := Matmul(attnW, V)
	return linear(ctx, bp.Wo, bp.Bo, seq)
}

func ffnBlock(x *Matrix, bp BlockParams, seq int) *Matrix {
	h := linear(x, bp.W1, bp.B1, seq)
	h = GeluMat(h)
	return linear(h, bp.W2, bp.B2, seq)
}

// Forward pass: ids []int -> logits (1 x vocab) for last token
func Forward(p *GPTParams, ids []int) *Matrix {
	cfg := p.Cfg
	seq := len(ids)

	// Embed
	x := NewMatrix(seq, cfg.DModel)
	for i, id := range ids {
		row := RowVec(p.TokenEmb, id)
		posRow := RowVec(p.PosEmb, i)
		combined := AddMat(row, posRow)
		SetRow(x, i, combined)
	}

	// Transformer blocks
	for _, bp := range p.Blocks {
		// Pre-LN attention
		x1 := LayerNormRows(x, bp.Ln1Scale, bp.Ln1Bias, 1e-5)
		attn := attentionBlock(x1, bp, seq, cfg.DModel)
		x = AddMat(x, attn)

		// Pre-LN FFN
		x2 := LayerNormRows(x, bp.Ln2Scale, bp.Ln2Bias, 1e-5)
		ff := ffnBlock(x2, bp, seq)
		x = AddMat(x, ff)
	}

	// Final LN on last token
	lastRow := RowVec(x, seq-1)
	normed := LayerNormRows(lastRow, p.FinalLnScale, p.FinalLnBias, 1e-5)

	// LM head
	logits := Matmul(normed, p.LMHead)
	// Add bias
	for c := 0; c < cfg.VocabSize; c++ {
		logits.Data[c] += p.LMBias.Data[c]
	}
	return logits
}

// CELoss: cross entropy for target class
func CELoss(logits *Matrix, target int) float32 {
	probs := Softmax1D(logits)
	v := probs.Data[target]
	if v < 1e-9 { v = 1e-9 }
	return float32(-math.Log(float64(v)))
}

