package main

import (
	"bufio"
	"fmt"
	"math"
	"math/rand"
	"os"
	"strconv"
	"strings"
	"time"

	"freelang-llm/model"
)

type AdamState struct {
	M *model.Matrix
	V *model.Matrix
	T int
}

func newAdam(rows, cols int) *AdamState {
	return &AdamState{M: model.ZeroMatrix(rows, cols), V: model.ZeroMatrix(rows, cols)}
}

func adamUpdate(param, grad *model.Matrix, s *AdamState, lr, b1, b2, eps float32) *model.Matrix {
	s.T++
	s.M = model.AddMat(model.ScaleMat(s.M, b1), model.ScaleMat(grad, 1-b1))
	s.V = model.AddMat(model.ScaleMat(s.V, b2), model.ScaleMat(model.Pow2Mat(grad), 1-b2))
	bc1 := float32(1.0 - math.Pow(float64(b1), float64(s.T)))
	bc2 := float32(1.0 - math.Pow(float64(b2), float64(s.T)))
	mhat := model.ScaleMat(s.M, 1/bc1)
	vhat := model.ScaleMat(s.V, 1/bc2)
	denom := model.AddScalarMat(model.SqrtMat(vhat), eps)
	delta := model.ScaleMat(model.DivElem(mhat, denom), lr)
	return model.SubMat(param, delta)
}

type Vocab struct {
	ByteToIdx [256]int
	IdxToByte []byte
	Size      int
}

func loadVocab(path string) (*Vocab, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()
	v := &Vocab{}
	for i := range v.ByteToIdx { v.ByteToIdx[i] = -1 }
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "vocab_size=") { continue }
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 { continue }
		idx, _ := strconv.Atoi(parts[0])
		byteVal, _ := strconv.Atoi(parts[1])
		v.ByteToIdx[byteVal] = idx
		if idx >= len(v.IdxToByte) {
			v.IdxToByte = append(v.IdxToByte, make([]byte, idx-len(v.IdxToByte)+1)...)
		}
		v.IdxToByte[idx] = byte(byteVal)
		if idx+1 > v.Size { v.Size = idx + 1 }
	}
	return v, nil
}

func encode(text string, v *Vocab) []int {
	ids := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ {
		if idx := v.ByteToIdx[text[i]]; idx >= 0 { ids = append(ids, idx) }
	}
	return ids
}

func linearFwd(x, W, b *model.Matrix, seq int) *model.Matrix {
	out := model.Matmul(x, W)
	for r := 0; r < seq; r++ {
		for c := 0; c < out.Cols; c++ {
			out.Data[r*out.Cols+c] += b.Data[c]
		}
	}
	return out
}

// Full forward pass returning ALL intermediate states for backprop
type ForwardCache struct {
	X       [][]float32 // embeddings at each layer input (seq x d)
	Xpre    [][]float32 // pre-attn LN outputs
	AttnOut [][]float32 // attention outputs
	Xmid    [][]float32 // after attn residual
	Xpre2   [][]float32 // pre-ffn LN outputs
	FfnOut  [][]float32 // ffn outputs
	XFinal  []float32   // final hidden before LN
	LNOut   []float32   // after final LN
	Logits  []float32   // logits
	Probs   []float32   // softmax probs
}

