func flattenRows(m *model.Matrix) [][]float32 {
	rows := make([][]float32, m.Rows)
	for r := 0; r < m.Rows; r++ {
		rows[r] = make([]float32, m.Cols)
		copy(rows[r], m.Data[r*m.Cols:(r+1)*m.Cols])
	}
	return rows
}

// Simplified: just compute loss with full forward + backprop on LMHead+TokenEmb
// For attention/ffn blocks we use numerical grad (per-step, sampled subset)
func trainStep(p *model.GPTParams, ids []int, target int,
	adamHead, adamBias, adamEmb *AdamState,
	lr, b1, b2, eps float32) float32 {

	cfg := p.Cfg
	seq := len(ids)

	// ── Forward ──────────────────────────────────────────
	x := model.NewMatrix(seq, cfg.DModel)
	for i, id := range ids {
		row := model.RowVec(p.TokenEmb, id)
		posRow := model.RowVec(p.PosEmb, i)
		model.SetRow(x, i, model.AddMat(row, posRow))
	}

	for _, bp := range p.Blocks {
		x1 := model.LayerNormRows(x, bp.Ln1Scale, bp.Ln1Bias, 1e-5)
		Q := linearFwd(x1, bp.Wq, bp.Bq, seq)
		K := linearFwd(x1, bp.Wk, bp.Bk, seq)
		V := linearFwd(x1, bp.Wv, bp.Bv, seq)
		scale := float32(1.0 / math.Sqrt(float64(cfg.DModel)))
		scores := model.AddMat(model.ScaleMat(model.Matmul(Q, model.Transpose(K)), scale), model.CausalMask(seq))
		attnW := model.SoftmaxRows(scores)
		ctx := model.Matmul(attnW, V)
		attn := linearFwd(ctx, bp.Wo, bp.Bo, seq)
		x = model.AddMat(x, attn)

		x2 := model.LayerNormRows(x, bp.Ln2Scale, bp.Ln2Bias, 1e-5)
		h := linearFwd(x2, bp.W1, bp.B1, seq)
		h = model.GeluMat(h)
		ff := linearFwd(h, bp.W2, bp.B2, seq)
		x = model.AddMat(x, ff)
	}

	lastRow := model.RowVec(x, seq-1)
	normed := model.LayerNormRows(lastRow, p.FinalLnScale, p.FinalLnBias, 1e-5)

	logits := model.Matmul(normed, p.LMHead)
	for c := 0; c < cfg.VocabSize; c++ { logits.Data[c] += p.LMBias.Data[c] }
	probs := model.Softmax1D(logits)

	// CE Loss
	pTarget := probs.Data[target]
	if pTarget < 1e-9 { pTarget = 1e-9 }
	loss := float32(-math.Log(float64(pTarget)))

	// ── Backprop through LM head ──────────────────────────
	dLogits := probs.Clone()
	dLogits.Data[target] -= 1.0

	dHead := model.Matmul(model.Transpose(normed), dLogits)
	dBias := dLogits.Clone()
	dNormed := model.Matmul(dLogits, model.Transpose(p.LMHead)) // (1 x d)

	p.LMHead = adamUpdate(p.LMHead, dHead, adamHead, lr, b1, b2, eps)
	p.LMBias = adamUpdate(p.LMBias, dBias, adamBias, lr, b1, b2, eps)

	// ── Backprop to token embeddings (via dNormed → dx) ──
	// Approximate: treat transformer as identity for embedding grad
	// dEmb[i] += dNormed for i == seq-1 position
	dEmb := model.NewMatrix(cfg.VocabSize, cfg.DModel)
	lastID := ids[seq-1]
	for c := 0; c < cfg.DModel; c++ {
		dEmb.Data[lastID*cfg.DModel+c] = dNormed.Data[c]
	}
	p.TokenEmb = adamUpdate(p.TokenEmb, dEmb, adamEmb, lr*0.1, b1, b2, eps)

	return loss
}

