cat > /tmp/trainer_full.go << 'GOEOF'
package main

import (
	"bufio"
	"fmt"
	"math"
	"math/rand"
	"os"
	"strconv"
	"strings"
	"time"
)

// ─── Tensor ─────────────────────────────────────────────────────────────────

type Mat struct {
	R, C int
	D    []float32
}

func newMat(r, c int) *Mat { return &Mat{R: r, C: c, D: make([]float32, r*c)} }
func (m *Mat) at(r, c int) float32 { return m.D[r*m.C+c] }
func (m *Mat) set(r, c int, v float32) { m.D[r*m.C+c] = v }
func (m *Mat) clone() *Mat {
	n := newMat(m.R, m.C); copy(n.D, m.D); return n
}

func randMat(r, c int, scale float32) *Mat {
	m := newMat(r, c)
	for i := range m.D { m.D[i] = (rand.Float32()*2 - 1) * scale }
	return m
}
func onesMat(n int) *Mat {
	m := newMat(1, n)
	for i := range m.D { m.D[i] = 1 }
	return m
}
func zeroMat(r, c int) *Mat { return newMat(r, c) }

func matmul(a, b *Mat) *Mat {
	// a: (m,k), b: (k,n) -> (m,n)
	m, k, n := a.R, a.C, b.C
	out := newMat(m, n)
	for i := 0; i < m; i++ {
		for p := 0; p < k; p++ {
			av := a.D[i*k+p]
			for j := 0; j < n; j++ {
				out.D[i*n+j] += av * b.D[p*n+j]
			}
		}
	}
	return out
}

func transpose(a *Mat) *Mat {
	out := newMat(a.C, a.R)
	for i := 0; i < a.R; i++ {
		for j := 0; j < a.C; j++ {
			out.D[j*a.R+i] = a.D[i*a.C+j]
		}
	}
	return out
}

func addMat(a, b *Mat) *Mat {
	out := a.clone()
	if b.R == 1 {
		for r := 0; r < a.R; r++ {
			for c := 0; c < a.C; c++ { out.D[r*a.C+c] += b.D[c] }
		}
	} else {
		for i := range out.D { out.D[i] += b.D[i] }
	}
	return out
}

func scaleMat(a *Mat, s float32) *Mat {
	out := a.clone()
	for i := range out.D { out.D[i] *= s }
	return out
}

func softmaxRows(a *Mat) *Mat {
	out := newMat(a.R, a.C)
	for r := 0; r < a.R; r++ {
		row := a.D[r*a.C : (r+1)*a.C]
		mx := row[0]
		for _, v := range row { if v > mx { mx = v } }
		var sum float32
		for c, v := range row {
			e := float32(math.Exp(float64(v - mx)))
			out.D[r*a.C+c] = e
			sum += e
		}
		for c := range row { out.D[r*a.C+c] /= sum }
	}
	return out
}

func softmax1D(a *Mat) *Mat {
	row := a.D
	mx := row[0]
	for _, v := range row { if v > mx { mx = v } }
	var sum float32
	out := newMat(1, a.C)
	for i, v := range row {
		e := float32(math.Exp(float64(v - mx)))
		out.D[i] = e
		sum += e
	}
	for i := range out.D { out.D[i] /= sum }
	return out
}

func geluMat(a *Mat) *Mat {
	out := a.clone()
	for i, v := range out.D {
		out.D[i] = float32(0.5 * float64(v) * (1.0 + math.Tanh(math.Sqrt(2.0/math.Pi)*(float64(v)+0.044715*math.Pow(float64(v), 3)))))
	}
	return out
}

func geluGrad(a, dout *Mat) *Mat {
	grad := newMat(a.R, a.C)
	for i, v := range a.D {
		x := float64(v)
		inner := math.Sqrt(2.0/math.Pi) * (x + 0.044715*x*x*x)
		tanhInner := math.Tanh(inner)
		dtanh := 1 - tanhInner*tanhInner
		dinnerDx := math.Sqrt(2.0/math.Pi) * (1 + 3*0.044715*x*x)
		dgelu := 0.5*(1+tanhInner) + 0.5*x*dtanh*dinnerDx
		grad.D[i] = float32(dgelu) * dout.D[i]
	}
	return grad
}

// LayerNorm: y = (x-mean)/std * scale + bias, returns (y, mean, rstd) per row
func layerNorm(x, scale, bias *Mat, eps float32) (y, mean, rstd *Mat) {
	y = newMat(x.R, x.C)
	mean = newMat(x.R, 1)
	rstd = newMat(x.R, 1)
	for r := 0; r < x.R; r++ {
		row := x.D[r*x.C : (r+1)*x.C]
		var m float32
		for _, v := range row { m += v }
		m /= float32(x.C)
		var v2 float32
		for _, v := range row { d := v - m; v2 += d * d }
		v2 /= float32(x.C)
		rs := float32(1.0 / math.Sqrt(float64(v2+float64(eps))))
		mean.D[r] = m
		rstd.D[r] = rs
		for c, v := range row {
			xhat := (v - m) * rs
			y.D[r*x.C+c] = xhat*scale.D[c] + bias.D[c]
		}
	}
	return
}

// LayerNorm backward: returns (dx, dscale, dbias)
func layerNormBackward(dout, x, scale, mean, rstd *Mat) (dx, dscale, dbias *Mat) {
	dx = newMat(x.R, x.C)
	dscale = newMat(1, x.C)
	dbias = newMat(1, x.C)
	N := float32(x.C)
	for r := 0; r < x.R; r++ {
		m := mean.D[r]
		rs := rstd.D[r]
		var dxhat_sum, dxhat_xhat_sum float32
		for c := 0; c < x.C; c++ {
			xhat := (x.D[r*x.C+c] - m) * rs
			dxhat := dout.D[r*x.C+c] * scale.D[c]
			dbias.D[c] += dout.D[r*x.C+c]
			dscale.D[c] += dout.D[r*x.C+c] * xhat
			dxhat_sum += dxhat
			dxhat_xhat_sum += dxhat * xhat
		}
		for c := 0; c < x.C; c++ {
			xhat := (x.D[r*x.C+c] - m) * rs
			dxhat := dout.D[r*x.C+c] * scale.D[c]
			dx.D[r*x.C+c] = rs * (dxhat - dxhat_sum/N - xhat*dxhat_xhat_sum/N)
		}
	}
	return
}

// Causal mask
func causalMask(seq int) *Mat {
	m := newMat(seq, seq)
	for i := range m.D { m.D[i] = float32(math.Inf(-1)) }
	for r := 0; r < seq; r++ {
		for c := 0; c <= r; c++ { m.D[r*seq+c] = 0 }
	}
	return m
}

// ─── Transformer Block Cache ──────────────────────────────────────────────────

type BlockCache struct {
	xIn                          *Mat // input to block
	ln1Out, ln1Mean, ln1Rstd     *Mat
	Q, K, V                      *Mat
	scores, attnW, attnCtx       *Mat
	attnOut, xMid                *Mat
	ln2Out, ln2Mean, ln2Rstd     *Mat
	h1, hAct, ffOut              *Mat
}

type Block struct {
	Wq, Wk, Wv, Wo *Mat
	Bq, Bk, Bv, Bo *Mat
	W1, B1, W2, B2 *Mat
	Ln1S, Ln1B     *Mat
	Ln2S, Ln2B     *Mat
}

func newBlock(d, ffn int) Block {
	s := float32(0.02)
	return Block{
		Wq: randMat(d, d, s), Wk: randMat(d, d, s), Wv: randMat(d, d, s), Wo: randMat(d, d, s),
		Bq: zeroMat(1, d), Bk: zeroMat(1, d), Bv: zeroMat(1, d), Bo: zeroMat(1, d),
		W1: randMat(d, ffn, s), B1: zeroMat(1, ffn), W2: randMat(ffn, d, s), B2: zeroMat(1, d),
		Ln1S: onesMat(d), Ln1B: zeroMat(1, d),
		Ln2S: onesMat(d), Ln2B: zeroMat(1, d),
	}
}

func linearFwd(x, W, b *Mat) *Mat {
	out := matmul(x, W)
	for r := 0; r < out.R; r++ {
		for c := 0; c < out.C; c++ { out.D[r*out.C+c] += b.D[c] }
	}
	return out
}

func blockFwd(x *Mat, b *Block, seq int) (*Mat, *BlockCache) {
	c := &BlockCache{xIn: x}
	c.ln1Out, c.ln1Mean, c.ln1Rstd = layerNorm(x, b.Ln1S, b.Ln1B, 1e-5)
	c.Q = linearFwd(c.ln1Out, b.Wq, b.Bq)
	c.K = linearFwd(c.ln1Out, b.Wk, b.Bk)
	c.V = linearFwd(c.ln1Out, b.Wv, b.Bv)
	sc := float32(1.0 / math.Sqrt(float64(x.C)))
	c.scores = addMat(scaleMat(matmul(c.Q, transpose(c.K)), sc), causalMask(seq))
	c.attnW = softmaxRows(c.scores)
	c.attnCtx = matmul(c.attnW, c.V)
	c.attnOut = linearFwd(c.attnCtx, b.Wo, b.Bo)
	c.xMid = addMat(x, c.attnOut)
	c.ln2Out, c.ln2Mean, c.ln2Rstd = layerNorm(c.xMid, b.Ln2S, b.Ln2B, 1e-5)
	c.h1 = linearFwd(c.ln2Out, b.W1, b.B1)
	c.hAct = geluMat(c.h1)
	c.ffOut = linearFwd(c.hAct, b.W2, b.B2)
	return addMat(c.xMid, c.ffOut), c
}

// blockBwd: dOut -> (dxIn, grads per block)
type BlockGrad struct {
	dWq, dWk, dWv, dWo *Mat
	dBq, dBk, dBv, dBo *Mat
	dW1, dB1, dW2, dB2 *Mat
	dLn1S, dLn1B       *Mat
	dLn2S, dLn2B       *Mat
}

func blockBwd(dOut *Mat, b *Block, c *BlockCache) (*Mat, *BlockGrad) {
	g := &BlockGrad{}
	seq := dOut.R; d := dOut.C

	// FFN residual
	dFfOut := dOut.clone()
	dXMid := dOut.clone()

	// FFN backward
	g.dB2 = zeroMat(1, d)
	for r := 0; r < seq; r++ {
		for col := 0; col < d; col++ { g.dB2.D[col] += dFfOut.D[r*d+col] }
	}
	g.dW2 = matmul(transpose(c.hAct), dFfOut)
	dHAct := matmul(dFfOut, transpose(b.W2))
	dH1 := geluGrad(c.h1, dHAct)
	g.dB1 = zeroMat(1, b.W1.C)
	for r := 0; r < seq; r++ {
		for col := 0; col < b.W1.C; col++ { g.dB1.D[col] += dH1.D[r*b.W1.C+col] }
	}
	g.dW1 = matmul(transpose(c.ln2Out), dH1)
	dLn2Out := matmul(dH1, transpose(b.W1))

	// LN2 backward
	var dLn2S, dLn2B *Mat
	dLn2Out2, dLn2S, dLn2B := layerNormBackward(dLn2Out, c.xMid, b.Ln2S, c.ln2Mean, c.ln2Rstd)
	g.dLn2S = dLn2S; g.dLn2B = dLn2B
	for i := range dXMid.D { dXMid.D[i] += dLn2Out2.D[i] }

	// Attention backward
	dAttnOut := dXMid.clone()
	dXIn := dXMid.clone()

	g.dBo = zeroMat(1, d)
	for r := 0; r < seq; r++ {
		for col := 0; col < d; col++ { g.dBo.D[col] += dAttnOut.D[r*d+col] }
	}
	g.dWo = matmul(transpose(c.attnCtx), dAttnOut)
	dAttnCtx := matmul(dAttnOut, transpose(b.Wo))

	// softmax backward: dscores = attnW * (dAttnCtx@V^T - sum(dAttnCtx*V_row)*attnW)
	dAttnW := matmul(dAttnCtx, transpose(c.V))
	dScores := newMat(seq, seq)
	for r := 0; r < seq; r++ {
		var sum float32
		for c2 := 0; c2 < seq; c2++ { sum += dAttnW.D[r*seq+c2] * c.attnW.D[r*seq+c2] }
		for c2 := 0; c2 < seq; c2++ {
			dScores.D[r*seq+c2] = c.attnW.D[r*seq+c2] * (dAttnW.D[r*seq+c2] - sum)
		}
	}
	// Clip for causal mask (already zeros beyond diagonal)
	dV := matmul(transpose(c.attnW), dAttnCtx)
	sc := float32(1.0 / math.Sqrt(float64(d)))
	dQ := scaleMat(matmul(dScores, c.K), sc)
	dK := scaleMat(matmul(transpose(dScores), c.Q), sc)

	g.dBq = zeroMat(1, d); g.dBk = zeroMat(1, d); g.dBv = zeroMat(1, d)
	for r := 0; r < seq; r++ {
		for col := 0; col < d; col++ {
			g.dBq.D[col] += dQ.D[r*d+col]
			g.dBk.D[col] += dK.D[r*d+col]
			g.dBv.D[col] += dV.D[r*d+col]
		}
	}
	g.dWq = matmul(transpose(c.ln1Out), dQ)
	g.dWk = matmul(transpose(c.ln1Out), dK)
	g.dWv = matmul(transpose(c.ln1Out), dV)
	dLn1Out := addMat(addMat(matmul(dQ, transpose(b.Wq)), matmul(dK, transpose(b.Wk))), matmul(dV, transpose(b.Wv)))

	// LN1 backward
	dLn1In, dLn1S, dLn1B := layerNormBackward(dLn1Out, c.xIn, b.Ln1S, c.ln1Mean, c.ln1Rstd)
	g.dLn1S = dLn1S; g.dLn1B = dLn1B
	for i := range dXIn.D { dXIn.D[i] += dLn1In.D[i] }

	return dXIn, g
}

// ─── Model ────────────────────────────────────────────────────────────────────

type GPT struct {
	VocabSize, D, NLayers, SeqLen, FFNDim int
	TokEmb, PosEmb                        *Mat
	Blocks                                []Block
	FLnS, FLnB                            *Mat
	LMHead, LMBias                        *Mat
}

func newGPT(vocab, d, layers, seq, ffn int) *GPT {
	s := float32(0.02)
	g := &GPT{VocabSize: vocab, D: d, NLayers: layers, SeqLen: seq, FFNDim: ffn}
	g.TokEmb = randMat(vocab, d, s)
	g.PosEmb = randMat(seq, d, s)
	g.FLnS = onesMat(d); g.FLnB = zeroMat(1, d)
	g.LMHead = randMat(d, vocab, s); g.LMBias = zeroMat(1, vocab)
	for i := 0; i < layers; i++ { g.Blocks = append(g.Blocks, newBlock(d, ffn)) }
	return g
}

// ─── Adam ─────────────────────────────────────────────────────────────────────

type Adam struct {
	m, v *Mat
	t    int
}

func newAdam(r, c int) *Adam { return &Adam{m: zeroMat(r, c), v: zeroMat(r, c)} }

func (a *Adam) step(param, grad *Mat, lr, b1, b2, eps float32) *Mat {
	a.t++
	out := param.clone()
	bc1 := float32(1 - math.Pow(float64(b1), float64(a.t)))
	bc2 := float32(1 - math.Pow(float64(b2), float64(a.t)))
	for i := range grad.D {
		a.m.D[i] = b1*a.m.D[i] + (1-b1)*grad.D[i]
		a.v.D[i] = b2*a.v.D[i] + (1-b2)*grad.D[i]*grad.D[i]
		mh := a.m.D[i] / bc1
		vh := a.v.D[i] / bc2
		out.D[i] -= lr * mh / (float32(math.Sqrt(float64(vh))) + eps)
	}
	return out
}

// ─── Vocab ────────────────────────────────────────────────────────────────────

type Vocab struct {
	ByteToIdx [256]int
	IdxToByte []byte
	Size      int
}

func loadVocab(path string) (*Vocab, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()
	v := &Vocab{}
	for i := range v.ByteToIdx { v.ByteToIdx[i] = -1 }
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if strings.HasPrefix(line, "vocab_size=") { continue }
		parts := strings.SplitN(line, "=", 2)
		if len(parts) != 2 { continue }
		idx, _ := strconv.Atoi(parts[0])
		bv, _ := strconv.Atoi(parts[1])
		v.ByteToIdx[bv] = idx
		for idx >= len(v.IdxToByte) { v.IdxToByte = append(v.IdxToByte, 0) }
		v.IdxToByte[idx] = byte(bv)
		if idx+1 > v.Size { v.Size = idx + 1 }
	}
	return v, nil
}

func encode(text string, v *Vocab) []int {
	ids := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ {
		if idx := v.ByteToIdx[text[i]]; idx >= 0 { ids = append(ids, idx) }
	}
	return ids
}

// ─── Save/Load ────────────────────────────────────────────────────────────────

func writeMat(w *bufio.Writer, name string, m *Mat) {
	fmt.Fprintf(w, "%s %d %d\n", name, m.R, m.C)
	sb := strings.Builder{}
	for i, v := range m.D {
		if i > 0 { sb.WriteByte(' ') }
		fmt.Fprintf(&sb, "%.6g", v)
	}
	fmt.Fprintln(w, sb.String())
}

func saveGPT(g *GPT, path string) {
	f, _ := os.Create(path); defer f.Close()
	w := bufio.NewWriterSize(f, 4*1024*1024)
	fmt.Fprintf(w, "vocab=%d dmodel=%d layers=%d seq=%d ffn=%d\n",
		g.VocabSize, g.D, g.NLayers, g.SeqLen, g.FFNDim)
	writeMat(w, "token_emb", g.TokEmb)
	writeMat(w, "pos_emb", g.PosEmb)
	for i, b := range g.Blocks {
		p := fmt.Sprintf("block%d", i)
		writeMat(w, p+"_wq", b.Wq); writeMat(w, p+"_wk", b.Wk)
		writeMat(w, p+"_wv", b.Wv); writeMat(w, p+"_wo", b.Wo)
		writeMat(w, p+"_bq", b.Bq); writeMat(w, p+"_bk", b.Bk)
		writeMat(w, p+"_bv", b.Bv); writeMat(w, p+"_bo", b.Bo)
		writeMat(w, p+"_w1", b.W1); writeMat(w, p+"_b1", b.B1)
		writeMat(w, p+"_w2", b.W2); writeMat(w, p+"_b2", b.B2)
		writeMat(w, p+"_ln1s", b.Ln1S); writeMat(w, p+"_ln1b", b.Ln1B)
		writeMat(w, p+"_ln2s", b.Ln2S); writeMat(w, p+"_ln2b", b.Ln2B)
	}
	writeMat(w, "final_ln_scale", g.FLnS)
	writeMat(w, "final_ln_bias", g.FLnB)
	writeMat(w, "lm_head", g.LMHead)
	writeMat(w, "lm_bias", g.LMBias)
	w.Flush()
}

// ─── Train Step ───────────────────────────────────────────────────────────────

type TrainState struct {
	aTokEmb, aPosEmb                *Adam
	aBlocks                         []blockAdam
	aFLnS, aFLnB                   *Adam
	aLMHead, aLMBias               *Adam
}

type blockAdam struct {
	Wq, Wk, Wv, Wo *Adam
	Bq, Bk, Bv, Bo *Adam
	W1, B1, W2, B2 *Adam
	Ln1S, Ln1B     *Adam
	Ln2S, Ln2B     *Adam
}

func newTrainState(g *GPT) *TrainState {
	ts := &TrainState{
		aTokEmb: newAdam(g.VocabSize, g.D),
		aPosEmb: newAdam(g.SeqLen, g.D),
		aFLnS:   newAdam(1, g.D), aFLnB: newAdam(1, g.D),
		aLMHead: newAdam(g.D, g.VocabSize), aLMBias: newAdam(1, g.VocabSize),
	}
	for range g.Blocks {
		ts.aBlocks = append(ts.aBlocks, blockAdam{
			Wq: newAdam(g.D, g.D), Wk: newAdam(g.D, g.D), Wv: newAdam(g.D, g.D), Wo: newAdam(g.D, g.D),
			Bq: newAdam(1, g.D), Bk: newAdam(1, g.D), Bv: newAdam(1, g.D), Bo: newAdam(1, g.D),
			W1: newAdam(g.D, g.FFNDim), B1: newAdam(1, g.FFNDim),
			W2: newAdam(g.FFNDim, g.D), B2: newAdam(1, g.D),
			Ln1S: newAdam(1, g.D), Ln1B: newAdam(1, g.D),
			Ln2S: newAdam(1, g.D), Ln2B: newAdam(1, g.D),
		})
	}
	return ts
}

func trainStep(g *GPT, ts *TrainState, ids []int, target int, lr, b1, b2, eps float32) float32 {
	seq := len(ids)

	// ── Forward ──
	x := newMat(seq, g.D)
	for i, id := range ids {
		for c := 0; c < g.D; c++ {
			x.D[i*g.D+c] = g.TokEmb.D[id*g.D+c] + g.PosEmb.D[i*g.D+c]
		}
	}

	caches := make([]*BlockCache, g.NLayers)
	for l := range g.Blocks {
		x, caches[l] = blockFwd(x, &g.Blocks[l], seq)
	}

	lastRow := newMat(1, g.D)
	copy(lastRow.D, x.D[(seq-1)*g.D:seq*g.D])

	lnOut, lnMean, lnRstd := layerNorm(lastRow, g.FLnS, g.FLnB, 1e-5)
	logits := linearFwd(lnOut, g.LMHead, g.LMBias)
	probs := softmax1D(logits)

	// ── Loss ──
	pTarget := probs.D[target]
	if pTarget < 1e-9 { pTarget = 1e-9 }
	loss := float32(-math.Log(float64(pTarget)))

	// ── Backward ──
	dLogits := probs.clone()
	dLogits.D[target] -= 1.0

	dLMBias := dLogits.clone()
	dLMHead := matmul(transpose(lnOut), dLogits)
	dLnOut := matmul(dLogits, transpose(g.LMHead))

	// LN backward (final)
	dLastRow, dFLnS, dFLnB := layerNormBackward(dLnOut, lastRow, g.FLnS, lnMean, lnRstd)

	// Scatter gradient to last row of x
	dX := newMat(seq, g.D)
	for c := 0; c < g.D; c++ { dX.D[(seq-1)*g.D+c] = dLastRow.D[c] }

	// Block backward (reverse)
	blockGrads := make([]*BlockGrad, g.NLayers)
	for l := g.NLayers - 1; l >= 0; l-- {
		dX, blockGrads[l] = blockBwd(dX, &g.Blocks[l], caches[l])
	}

	// Embedding gradient
	dTokEmb := newMat(g.VocabSize, g.D)
	dPosEmb := newMat(g.SeqLen, g.D)
	for i, id := range ids {
		for c := 0; c < g.D; c++ {
			dTokEmb.D[id*g.D+c] += dX.D[i*g.D+c]
			dPosEmb.D[i*g.D+c] += dX.D[i*g.D+c]
		}
	}

	// ── Parameter Update ──
	g.TokEmb = ts.aTokEmb.step(g.TokEmb, dTokEmb, lr, b1, b2, eps)
	g.PosEmb = ts.aPosEmb.step(g.PosEmb, dPosEmb, lr*0.1, b1, b2, eps)
	g.FLnS = ts.aFLnS.step(g.FLnS, dFLnS, lr, b1, b2, eps)
	g.FLnB = ts.aFLnB.step(g.FLnB, dFLnB, lr, b1, b2, eps)
	g.LMHead = ts.aLMHead.step(g.LMHead, dLMHead, lr, b1, b2, eps)
	g.LMBias = ts.aLMBias.step(g.LMBias, dLMBias, lr, b1, b2, eps)

	for l := range g.Blocks {
		bg := blockGrads[l]
		ba := &ts.aBlocks[l]
		b := &g.Blocks[l]
		b.Wq = ba.Wq.step(b.Wq, bg.dWq, lr, b1, b2, eps)
		b.Wk = ba.Wk.step(b.Wk, bg.dWk, lr, b1, b2, eps)
		b.Wv = ba.Wv.step(b.Wv, bg.dWv, lr, b1, b2, eps)
		b.Wo = ba.Wo.step(b.Wo, bg.dWo, lr, b1, b2, eps)
		b.Bq = ba.Bq.step(b.Bq, bg.dBq, lr, b1, b2, eps)
		b.Bk = ba.Bk.step(b.Bk, bg.dBk, lr, b1, b2, eps)
		b.Bv = ba.Bv.step(b.Bv, bg.dBv, lr, b1, b2, eps)
		b.Bo = ba.Bo.step(b.Bo, bg.dBo, lr, b1, b2, eps)
		b.W1 = ba.W1.step(b.W1, bg.dW1, lr, b1, b2, eps)
		b.B1 = ba.B1.step(b.B1, bg.dB1, lr, b1, b2, eps)
		b.W2 = ba.W2.step(b.W2, bg.dW2, lr, b1, b2, eps)
		b.B2 = ba.B2.step(b.B2, bg.dB2, lr, b1, b2, eps)
		b.Ln1S = ba.Ln1S.step(b.Ln1S, bg.dLn1S, lr, b1, b2, eps)
		b.Ln1B = ba.Ln1B.step(b.Ln1B, bg.dLn1B, lr, b1, b2, eps)
		b.Ln2S = ba.Ln2S.step(b.Ln2S, bg.dLn2S, lr, b1, b2, eps)
		b.Ln2B = ba.Ln2B.step(b.Ln2B, bg.dLn2B, lr, b1, b2, eps)
	}

	return loss
}

// ─── Top-k Sampling ───────────────────────────────────────────────────────────

func topKSample(logits *Mat, k int, temp float32) int {
	n := logits.C
	if k <= 0 || k > n { k = n }
	type pair struct{ idx int; val float32 }
	pairs := make([]pair, n)
	for i, v := range logits.D { pairs[i] = pair{i, v / temp} }
	for i := 0; i < k; i++ {
		mx := i
		for j := i + 1; j < n; j++ { if pairs[j].val > pairs[mx].val { mx = j } }
		pairs[i], pairs[mx] = pairs[mx], pairs[i]
	}
	topK := pairs[:k]
	maxV := topK[0].val
	probs := make([]float32, k)
	var sum float32
	for i, p := range topK {
		probs[i] = float32(math.Exp(float64(p.val - maxV)))
		sum += probs[i]
	}
	for i := range probs { probs[i] /= sum }
	r := rand.Float32()
	var cum float32
	for i, p := range probs {
		cum += p
		if r <= cum { return topK[i].idx }
	}
	return topK[k-1].idx
}

// ─── Generate ─────────────────────────────────────────────────────────────────

func generate(g *GPT, prompt []int, maxNew int, temp float32) []int {
	ids := make([]int, len(prompt))
	copy(ids, prompt)
	for i := 0; i < maxNew; i++ {
		ctx := ids
		if len(ctx) > g.SeqLen { ctx = ctx[len(ctx)-g.SeqLen:] }
		seq := len(ctx)
		x := newMat(seq, g.D)
		for j, id := range ctx {
			for c := 0; c < g.D; c++ {
				x.D[j*g.D+c] = g.TokEmb.D[id*g.D+c] + g.PosEmb.D[j*g.D+c]
			}
		}
		for l := range g.Blocks {
			x, _ = blockFwd(x, &g.Blocks[l], seq)
		}
		lastRow := newMat(1, g.D)
		copy(lastRow.D, x.D[(seq-1)*g.D:seq*g.D])
		lnOut, _, _ := layerNorm(lastRow, g.FLnS, g.FLnB, 1e-5)
		logits := linearFwd(lnOut, g.LMHead, g.LMBias)
		next := topKSample(logits, 5, temp)
		ids = append(ids, next)
	}
	return ids[len(prompt):]
}

// ─── Main ─────────────────────────────────────────────────────────────────────

func main() {
	rand.Seed(time.Now().UnixNano())
	dataDir := os.ExpandEnv("$HOME/projects/freelang-llm/data")
	modelPath := os.ExpandEnv("$HOME/projects/freelang-llm/model/model_v2.bin")

	v, err := loadVocab(dataDir + "/vocab.txt")
	if err != nil { fmt.Fprintf(os.Stderr, "vocab: %v\n", err); os.Exit(1) }
	fmt.Printf("vocab=%d\n", v.Size)

	corpusBytes, _ := os.ReadFile(dataDir + "/corpus.txt")
	corpus := encode(string(corpusBytes), v)
	fmt.Printf("tokens=%d\n", len(corpus))

