	steps := 30000
	seqLen := 64
	batchPrint := 500

	fmt.Printf("=== Full Backprop GPT Training ===\nsteps=%d, seq=%d, lr=%.4f\n\n", steps, seqLen, lr)

	var runLoss float32
	for step := 1; step <= steps; step++ {
		// Random window
		start := rand.Intn(len(corpus) - seqLen - 1)
		ctx := corpus[start : start+seqLen]
		target := corpus[start+seqLen]

		loss := trainStep(g, ts, ctx, target, lr, b1, b2, eps)
		runLoss += loss

		if step%batchPrint == 0 {
			avg := runLoss / float32(batchPrint)
			ppl := math.Exp(float64(avg))
			fmt.Printf("step %5d | loss %.4f | ppl %7.2f\n", step, avg, ppl)
			runLoss = 0

			// Quick generate sample
			sampleStart := rand.Intn(len(corpus) - 10)
			seed := corpus[sampleStart : sampleStart+5]
