			for _, id := range seed {
				if id < len(v.IdxToByte) { seedTxt = append(seedTxt, v.IdxToByte[id]) }
			}
			genTxt := make([]byte, 0, 50)
			for _, id := range generated {
				if id < len(v.IdxToByte) { genTxt = append(genTxt, v.IdxToByte[id]) }
			}
			fmt.Printf("  sample: %s|%s\n\n", string(seedTxt), string(genTxt))
		}
	}

	saveGPT(g, modelPath)
	fmt.Println("\n학습 완료:", modelPath)
}
