package main

import (
	"bufio"
	"fmt"
	"math"
	"math/rand"
	"os"
	"strconv"
	"strings"
	"time"
)

// (모든 Mat, layerNorm, matmul 등 동일 — trainer_full.go에서 복사)

type Mat struct{ R, C int; D []float32 }
func newMat(r, c int) *Mat { return &Mat{R: r, C: c, D: make([]float32, r*c)} }
func (m *Mat) clone() *Mat { n := newMat(m.R, m.C); copy(n.D, m.D); return n }

func matmul(a, b *Mat) *Mat {
	m, k, n := a.R, a.C, b.C
	out := newMat(m, n)
	for i := 0; i < m; i++ {
		for p := 0; p < k; p++ {
			av := a.D[i*k+p]
			for j := 0; j < n; j++ { out.D[i*n+j] += av * b.D[p*n+j] }
		}
	}
	return out
}
func transpose(a *Mat) *Mat {
	out := newMat(a.C, a.R)
	for i := 0; i < a.R; i++ { for j := 0; j < a.C; j++ { out.D[j*a.R+i] = a.D[i*a.C+j] } }
	return out
}
func addMat(a, b *Mat) *Mat {
	out := a.clone()
	if b.R == 1 { for r := 0; r < a.R; r++ { for c := 0; c < a.C; c++ { out.D[r*a.C+c] += b.D[c] } } } else { for i := range out.D { out.D[i] += b.D[i] } }
	return out
}
func scaleMat(a *Mat, s float32) *Mat { out := a.clone(); for i := range out.D { out.D[i] *= s }; return out }
func softmaxRows(a *Mat) *Mat {
	out := newMat(a.R, a.C)
	for r := 0; r < a.R; r++ {
		row := a.D[r*a.C : (r+1)*a.C]; mx := row[0]
		for _, v := range row { if v > mx { mx = v } }
		var sum float32
		for c, v := range row { e := float32(math.Exp(float64(v - mx))); out.D[r*a.C+c] = e; sum += e }
		for c := range row { out.D[r*a.C+c] /= sum }
	}
	return out
}
func geluMat(a *Mat) *Mat {
	out := a.clone()
	for i, v := range out.D { out.D[i] = float32(0.5*float64(v)*(1+math.Tanh(math.Sqrt(2/math.Pi)*(float64(v)+0.044715*math.Pow(float64(v),3))))) }
	return out
}
func layerNorm(x, scale, bias *Mat, eps float32) *Mat {
	out := newMat(x.R, x.C)
	for r := 0; r < x.R; r++ {
		row := x.D[r*x.C : (r+1)*x.C]; var m float32
		for _, v := range row { m += v }; m /= float32(x.C)
		var v2 float32
		for _, v := range row { d := v - m; v2 += d * d }; v2 /= float32(x.C)
		rs := float32(1.0 / math.Sqrt(float64(v2)+float64(eps)))
		for c, v := range row { out.D[r*x.C+c] = (v-m)*rs*scale.D[c] + bias.D[c] }
	}
	return out
}
func causalMask(seq int) *Mat {
	m := newMat(seq, seq)
	for i := range m.D { m.D[i] = float32(math.Inf(-1)) }
	for r := 0; r < seq; r++ { for c := 0; c <= r; c++ { m.D[r*seq+c] = 0 } }
	return m
}
func linearFwd(x, W, b *Mat) *Mat {
	out := matmul(x, W)
	for r := 0; r < out.R; r++ { for c := 0; c < out.C; c++ { out.D[r*out.C+c] += b.D[c] } }
	return out
}

type Block struct{ Wq, Wk, Wv, Wo, Bq, Bk, Bv, Bo, W1, B1, W2, B2, Ln1S, Ln1B, Ln2S, Ln2B *Mat }
type GPT struct {
	VocabSize, D, NLayers, SeqLen, FFNDim int
	TokEmb, PosEmb, FLnS, FLnB, LMHead, LMBias *Mat
	Blocks []Block
}

func (g *GPT) forward(ids []int) *Mat {
	seq := len(ids)
	x := newMat(seq, g.D)
	for i, id := range ids { for c := 0; c < g.D; c++ { x.D[i*g.D+c] = g.TokEmb.D[id*g.D+c] + g.PosEmb.D[i*g.D+c] } }
	for _, b := range g.Blocks {
		ln1 := layerNorm(x, b.Ln1S, b.Ln1B, 1e-5)
		Q := linearFwd(ln1, b.Wq, b.Bq); K := linearFwd(ln1, b.Wk, b.Bk); V := linearFwd(ln1, b.Wv, b.Bv)
		sc := float32(1.0 / math.Sqrt(float64(g.D)))
		scores := addMat(scaleMat(matmul(Q, transpose(K)), sc), causalMask(seq))
		attnW := softmaxRows(scores); ctx := matmul(attnW, V)
		attn := linearFwd(ctx, b.Wo, b.Bo); x = addMat(x, attn)
		ln2 := layerNorm(x, b.Ln2S, b.Ln2B, 1e-5)
		h := geluMat(linearFwd(ln2, b.W1, b.B1))
		x = addMat(x, linearFwd(h, b.W2, b.B2))
	}
	last := newMat(1, g.D); copy(last.D, x.D[(seq-1)*g.D:seq*g.D])
	ln := layerNorm(last, g.FLnS, g.FLnB, 1e-5)
	return linearFwd(ln, g.LMHead, g.LMBias)
}

func loadModel(path string) (*GPT, error) {
	f, err := os.Open(path)
	if err != nil { return nil, err }
	defer f.Close()
	sc := bufio.NewScanner(f); sc.Buffer(make([]byte, 64<<20), 64<<20)
	sc.Scan(); header := sc.Text()
	g := &GPT{}
	for _, part := range strings.Fields(header) {
		kv := strings.SplitN(part, "=", 2)
		if len(kv) != 2 { continue }
		v, _ := strconv.Atoi(kv[1])
		switch kv[0] { case "vocab": g.VocabSize=v; case "dmodel": g.D=v; case "layers": g.NLayers=v; case "seq": g.SeqLen=v; case "ffn": g.FFNDim=v }
	}
	allMats := map[string]**Mat{}
	g.TokEmb = newMat(g.VocabSize, g.D); allMats["token_emb"] = &g.TokEmb
	g.PosEmb = newMat(g.SeqLen, g.D);    allMats["pos_emb"] = &g.PosEmb
	g.FLnS = newMat(1, g.D);             allMats["final_ln_scale"] = &g.FLnS
	g.FLnB = newMat(1, g.D);             allMats["final_ln_bias"] = &g.FLnB
	g.LMHead = newMat(g.D, g.VocabSize); allMats["lm_head"] = &g.LMHead
	g.LMBias = newMat(1, g.VocabSize);   allMats["lm_bias"] = &g.LMBias
	for i := 0; i < g.NLayers; i++ {
		b := Block{Wq:newMat(g.D,g.D),Wk:newMat(g.D,g.D),Wv:newMat(g.D,g.D),Wo:newMat(g.D,g.D),
			Bq:newMat(1,g.D),Bk:newMat(1,g.D),Bv:newMat(1,g.D),Bo:newMat(1,g.D),
			W1:newMat(g.D,g.FFNDim),B1:newMat(1,g.FFNDim),W2:newMat(g.FFNDim,g.D),B2:newMat(1,g.D),
			Ln1S:newMat(1,g.D),Ln1B:newMat(1,g.D),Ln2S:newMat(1,g.D),Ln2B:newMat(1,g.D)}
		g.Blocks = append(g.Blocks, b)
		p := fmt.Sprintf("block%d", i)
		allMats[p+"_wq"]=&g.Blocks[i].Wq; allMats[p+"_wk"]=&g.Blocks[i].Wk
		allMats[p+"_wv"]=&g.Blocks[i].Wv; allMats[p+"_wo"]=&g.Blocks[i].Wo
		allMats[p+"_bq"]=&g.Blocks[i].Bq; allMats[p+"_bk"]=&g.Blocks[i].Bk
		allMats[p+"_bv"]=&g.Blocks[i].Bv; allMats[p+"_bo"]=&g.Blocks[i].Bo
		allMats[p+"_w1"]=&g.Blocks[i].W1; allMats[p+"_b1"]=&g.Blocks[i].B1
		allMats[p+"_w2"]=&g.Blocks[i].W2; allMats[p+"_b2"]=&g.Blocks[i].B2
		allMats[p+"_ln1s"]=&g.Blocks[i].Ln1S; allMats[p+"_ln1b"]=&g.Blocks[i].Ln1B
		allMats[p+"_ln2s"]=&g.Blocks[i].Ln2S; allMats[p+"_ln2b"]=&g.Blocks[i].Ln2B
	}
	for sc.Scan() {
		nameLine := sc.Text(); parts := strings.Fields(nameLine)
		if len(parts) < 3 { continue }
		name := parts[0]; rows, _ := strconv.Atoi(parts[1]); cols, _ := strconv.Atoi(parts[2])
		sc.Scan(); vals := strings.Fields(sc.Text())
		m := newMat(rows, cols)
		for i, s := range vals { if i < len(m.D) { v, _ := strconv.ParseFloat(s, 32); m.D[i] = float32(v) } }
		if ptr, ok := allMats[name]; ok { *ptr = m }
	}
	return g, nil
}

type Vocab struct{ ByteToIdx [256]int; IdxToByte []byte; Size int }
func loadVocab(path string) (*Vocab, error) {
	f, err := os.Open(path); if err != nil { return nil, err }; defer f.Close()
	v := &Vocab{}; for i := range v.ByteToIdx { v.ByteToIdx[i] = -1 }
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text(); if strings.HasPrefix(line, "vocab_size=") { continue }
		parts := strings.SplitN(line, "=", 2); if len(parts) != 2 { continue }
		idx, _ := strconv.Atoi(parts[0]); bv, _ := strconv.Atoi(parts[1])
		v.ByteToIdx[bv] = idx
		for idx >= len(v.IdxToByte) { v.IdxToByte = append(v.IdxToByte, 0) }
		v.IdxToByte[idx] = byte(bv); if idx+1 > v.Size { v.Size = idx+1 }
	}
	return v, nil
}
func encode(text string, v *Vocab) []int {
	ids := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ { if idx := v.ByteToIdx[text[i]]; idx >= 0 { ids = append(ids, idx) } }
	return ids
}

func topKSample(logits *Mat, k int, temp float32) int {
	n := logits.C; if k <= 0 || k > n { k = n }
	type pair struct{ idx int; val float32 }
	pairs := make([]pair, n)
	for i, v := range logits.D { pairs[i] = pair{i, v / temp} }
	for i := 0; i < k; i++ { mx := i; for j := i+1; j < n; j++ { if pairs[j].val > pairs[mx].val { mx = j } }; pairs[i], pairs[mx] = pairs[mx], pairs[i] }
	topK := pairs[:k]; maxV := topK[0].val; probs := make([]float32, k); var sum float32
	for i, p := range topK { probs[i] = float32(math.Exp(float64(p.val-maxV))); sum += probs[i] }
	for i := range probs { probs[i] /= sum }
	r := rand.Float32(); var cum float32
	for i, p := range probs { cum += p; if r <= cum { return topK[i].idx } }
	return topK[k-1].idx
}

func main() {
	rand.Seed(time.Now().UnixNano())
	dataDir := os.ExpandEnv("$HOME/projects/freelang-llm/data")
	modelPath := os.ExpandEnv("$HOME/projects/freelang-llm/model/model_v2.bin")

	v, _ := loadVocab(dataDir + "/vocab.txt")
	g, err := loadModel(modelPath)
	if err != nil { fmt.Fprintln(os.Stderr, err); os.Exit(1) }
	fmt.Printf("모델 로드: vocab=%d, d=%d, layers=%d, seq=%d\n\n", g.VocabSize, g.D, g.NLayers, g.SeqLen)
	fmt.Println("=== FreeLang LLM (Full Backprop) ===")
	fmt.Println("프롬프트 입력 (exit 종료):")

	scanner := bufio.NewScanner(os.Stdin)
	for {
		fmt.Print("\n> "); if !scanner.Scan() { break }
		prompt := scanner.Text()
		if prompt == "exit" || prompt == "quit" { break }
		if prompt == "" { continue }
		ids := encode(prompt, v)
		if len(ids) == 0 { fmt.Println("인코딩 실패"); continue }
		if len(ids) > g.SeqLen { ids = ids[len(ids)-g.SeqLen:] }
		fmt.Printf("[생성 중...]\n%s", prompt)

		for i := 0; i < 150; i++ {
			ctx := ids; if len(ctx) > g.SeqLen { ctx = ctx[len(ctx)-g.SeqLen:] }
			logits := g.forward(ctx)
			next := topKSample(logits, 5, 0.8)
			ids = append(ids, next)
			if next < len(v.IdxToByte) { fmt.Printf("%c", v.IdxToByte[next]) }
		}
		fmt.Println()
	}
}
